func publish(_ draft: Draft) throws -> Published {
    guard let body = draft.body else {
        throw DraftError.missingBody          // guard: bad input
    }
    guard draft.readyAt <= clock.now else {
        throw DraftError.notReady             // guard: state
    }
    return try repo.publish(body)             // body is non-optional here
}

