func withdraw(_ amount: Decimal) {
    precondition(amount > 0, "amount must be positive")     // programmer contract
    precondition(balance >= amount, "balance must cover withdrawal")
    switch state {
    case .open:   balance -= amount
    case .closed: preconditionFailure("account closed")      // impossible branch
    }
}
